# 计算爆款潜力值
describe_1 = file_scaler_data['标准化第三期销量'].describe()[4]   # 25%
describe_2 = file_scaler_data['标准化第三期销量'].describe()[5]   # 50%
describe_3 = file_scaler_data['标准化第三期销量'].describe()[6]   # 75%
# 区间权重： x<=25% : 1; 25%<x<=50% : 0.7; 50%<x<=75% : 0.4; x>75% : 0.1;
# 指标权重： 标准化近一年销量3: 0.1;  标准化上期增幅: 0.3;  标准化本期增幅: 0.6;
for v in range(len(file_good_scaler['挖掘日期'])):
    if file_good_scaler['标准化第三期销量'][v] <= describe_1:
        file_good_scaler.loc[v, '爆款潜力值'] = file_good_scaler.loc[v,'标准化第三期销量']*1*0.1 + file_good_scaler.loc[v,'标准化上期增幅']*0.3 + file_good_scaler.loc[v,'标准化本期增幅']*0.6
    elif (file_good_scaler[ '标准化第三期销量'][v] > describe_1) & (file_good_scaler['标准化第三期销量'][v] <= describe_2):
        file_good_scaler.loc[v,'爆款潜力值'] = file_good_scaler.loc[v,'标准化第三期销量'] * 0.7 * 0.1 + file_good_scaler.loc[v,'标准化上期增幅'] * 0.3 + file_good_scaler.loc[v,'标准化本期增幅'] * 0.6
    elif (file_good_scaler['标准化第三期销量'][v] > describe_2) & (file_good_scaler['标准化第三期销量'][v] <= describe_3):
        file_good_scaler.loc[v,'爆款潜力值'] = file_good_scaler.loc[v,'标准化第三期销量'] * 0.4 * 0.1 + file_good_scaler.loc[v,'标准化上期增幅'] * 0.3 + file_good_scaler.loc[v,'标准化本期增幅'] * 0.6   # 不同写法
    else:
        file_good_scaler.loc[v,'爆款潜力值'] = file_good_scaler.loc[v,'标准化第三期销量'] * 0.1 * 0.1 + file_good_scaler.loc[v,'标准化上期增幅'] * 0.3 + file_good_scaler.loc[v,'标准化本期增幅'] * 0.6
file_good_scaler = file_good_scaler.sort_values('爆款潜力值',ascending=False) # 按照'爆款潜力值'列对file_good_scaler数据框进行降序排序。
